import { createHash } from "node:crypto";
import fs from "node:fs/promises";
import path from "node:path";
import { z } from "zod";
import { PROJECT_CONTEXT_TOPICS, } from "./project-context.js";
import { extractProjectContextSections, loadProjectContextModuleManifest } from "./project-context-loader.js";
import { auditMssrProjectContextHealth } from "./project-context-health.js";
const idSchema = z.string().regex(/^[a-z0-9][a-z0-9._-]{1,79}$/);
function slug(value) {
    const normalized = value
        .normalize("NFKD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .replace(/^#{1,6}\s+/, "")
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, 44);
    return normalized || "section";
}
function boundedId(base, suffix) {
    const joined = `${base}.${suffix}`.replace(/[^a-z0-9._-]+/g, "-").toLowerCase();
    const clipped = joined.slice(0, 80).replace(/[-._]+$/g, "");
    return idSchema.parse(clipped.length >= 2 ? clipped : `${base}.section`.slice(0, 80));
}
function inferredTopic(entry) {
    if (entry.topic && PROJECT_CONTEXT_TOPICS.includes(entry.topic))
        return entry.topic;
    if (entry.kind === "state")
        return "state";
    if (entry.kind === "memory")
        return "decision";
    if (entry.kind === "directive")
        return "operations";
    return "reference";
}
function headingLevel(line) {
    const match = /^(#{1,6})\s+\S/.exec(line.trim());
    return match ? match[1].length : null;
}
function enumerateSections(markdown, level = 2) {
    const lines = markdown.replace(/\r\n/g, "\n").split("\n");
    const out = [];
    for (let start = 0; start < lines.length; start += 1) {
        const currentLevel = headingLevel(lines[start]);
        if (currentLevel !== level)
            continue;
        let end = lines.length;
        for (let index = start + 1; index < lines.length; index += 1) {
            const nextLevel = headingLevel(lines[index]);
            if (nextLevel !== null && nextLevel <= level) {
                end = index;
                break;
            }
        }
        const text = lines.slice(start, end).join("\n").trim();
        out.push({
            heading: lines[start].trim(),
            level,
            chars: Buffer.byteLength(text, "utf8"),
            sha256: createHash("sha256").update(text, "utf8").digest("hex"),
        });
    }
    return out.sort((a, b) => b.chars - a.chars || a.heading.localeCompare(b.heading));
}
async function readManifest(projectRoot) {
    const loaded = await loadProjectContextModuleManifest(projectRoot);
    if (!loaded.found)
        throw new Error("Project-context manifest is missing.");
    return loaded.manifest;
}
async function selectedSectionBytes(projectRoot, sourcePath, heading) {
    const text = await fs.readFile(path.resolve(projectRoot, sourcePath), "utf8");
    const selected = extractProjectContextSections(text, [heading]);
    return {
        chars: Buffer.byteLength(selected, "utf8"),
        sha256: createHash("sha256").update(selected, "utf8").digest("hex"),
    };
}
export async function planMssrProjectContextModularization(projectRootInput) {
    const projectRoot = path.resolve(projectRootInput);
    const health = await auditMssrProjectContextHealth(projectRoot);
    if (health.manifestStatus !== "valid") {
        return {
            projectRoot,
            health,
            status: "blocked",
            reason: "project-context-not-initialized",
            candidates: [],
            authoritySections: [],
            advisoryOnly: true,
        };
    }
    const manifest = await readManifest(projectRoot);
    const entries = [
        ...manifest.core.map((entry) => ({ entry, core: true })),
        ...manifest.modules.map((entry) => ({ entry, core: false })),
    ];
    const pressuredIds = new Set(health.findings
        .filter((finding) => finding.code === "oversized-core-module"
        || finding.code === "growing-core-module"
        || finding.code === "oversized-module"
        || finding.code === "growing-module"
        || finding.code === "core-entry-budget-pressure"
        || finding.code === "core-entry-budget-exceeded"
        || finding.code === "module-entry-budget-pressure"
        || finding.code === "module-entry-budget-exceeded")
        .map((finding) => finding.target));
    const pressuredAuthorities = new Set(health.findings
        .filter((finding) => finding.code === "oversized-authority"
        || finding.code === "growing-authority"
        || finding.code === "root-backed-memory-fanout")
        .map((finding) => finding.target.toLowerCase()));
    const referenceStoragePressuredAuthorities = new Set(health.findings
        .filter((finding) => finding.code === "root-backed-memory-fanout")
        .map((finding) => finding.target.toLowerCase()));
    const budgetPressuredWholeFileSources = new Set(entries
        .filter(({ entry }) => pressuredIds.has(entry.id)
        && !(entry.source.sections?.length)
        && !("segments" in entry && entry.segments?.length)
        && !("references" in entry && entry.references?.length))
        .map(({ entry }) => entry.source.path.replace(/\\/g, "/").toLowerCase()));
    const candidates = [];
    const indexedHeadings = new Map();
    for (const { entry, core } of entries) {
        const normalizedPath = entry.source.path.replace(/\\/g, "/");
        const sourceKey = normalizedPath.toLowerCase();
        const headings = entry.source.sections ?? [];
        if (!indexedHeadings.has(sourceKey))
            indexedHeadings.set(sourceKey, new Set());
        for (const heading of headings)
            indexedHeadings.get(sourceKey).add(heading);
        const entryPressured = pressuredIds.has(entry.id);
        const authorityPressured = pressuredAuthorities.has(normalizedPath.toLowerCase());
        if (!entryPressured && !authorityPressured)
            continue;
        if (!headings.length)
            continue;
        for (const heading of headings) {
            let materialized;
            try {
                materialized = await selectedSectionBytes(projectRoot, normalizedPath, heading);
            }
            catch {
                continue;
            }
            const referenceStoragePressure = referenceStoragePressuredAuthorities.has(sourceKey);
            if (materialized.chars < 1_000 && !entryPressured && !referenceStoragePressure)
                continue;
            const topic = inferredTopic(entry);
            const suffix = slug(heading);
            const preserveModuleId = !core && headings.length === 1;
            const moduleId = preserveModuleId ? entry.id : boundedId(entry.id, suffix);
            const fileName = `${moduleId.replace(/[.]+/g, "-")}.md`;
            const suggestedPath = path.posix.join(".mssr", "knowledge", topic, fileName);
            // A section already stored at its canonical knowledge path cannot be
            // meaningfully extracted again. Keep its health finding visible, but do
            // not report a self-move with the same source and destination.
            if (sourceKey === suggestedPath.toLowerCase())
                continue;
            candidates.push({
                action: "extract-indexed-section",
                entryId: entry.id,
                core,
                sourcePath: normalizedPath,
                heading,
                chars: materialized.chars,
                sha256: materialized.sha256,
                topic,
                topicInferred: !entry.topic,
                area: entry.area ?? null,
                suggestedPath,
                suggestedModuleId: moduleId,
                preserveModuleId,
                preserveSelectorsFrom: entry.id,
                preserveKind: entry.kind,
                requiresCoreDecision: core,
                rationale: core
                    ? "Core pressure requires an explicit decision about which minimum invariant remains always loaded."
                    : referenceStoragePressure && entry.kind === "memory"
                        ? "Optional memory is semantically modular already; move the exact indexed section to a reference-backed knowledge file while preserving its module id, kind and selectors."
                        : "Move exact indexed section bytes to knowledge/ and preserve the parent module selectors; no semantic rewrite is required.",
            });
        }
    }
    const authoritySections = [];
    const sectionInspectionSources = new Set([
        ...pressuredAuthorities,
        ...budgetPressuredWholeFileSources,
    ]);
    for (const sourceKey of [...sectionInspectionSources].sort()) {
        const entry = entries.find(({ entry }) => entry.source.path.replace(/\\/g, "/").toLowerCase() === sourceKey);
        const rel = entry?.entry.source.path.replace(/\\/g, "/") ?? sourceKey;
        let text;
        try {
            text = await fs.readFile(path.resolve(projectRoot, rel), "utf8");
        }
        catch {
            continue;
        }
        const indexed = indexedHeadings.get(sourceKey) ?? new Set();
        authoritySections.push({
            authority: rel,
            pressureSource: budgetPressuredWholeFileSources.has(sourceKey) ? "entry-budget" : "authority-size",
            requiresSelectorReview: budgetPressuredWholeFileSources.has(sourceKey),
            largestSections: enumerateSections(text)
                .slice(0, 12)
                .map((section) => ({
                ...section,
                indexed: indexed.has(section.heading),
                recommendation: indexed.has(section.heading)
                    ? "EXTRACT_INDEXED_SECTION"
                    : section.chars >= 1_000 && budgetPressuredWholeFileSources.has(sourceKey)
                        ? "REVIEW_FOR_MODULE_SPLIT"
                        : section.chars >= 4_000
                            ? "REVIEW_FOR_KNOWLEDGE_CAPTURE"
                            : "KEEP_OR_CURATE",
            })),
        });
    }
    return {
        projectRoot,
        health,
        status: health.level === "ok" ? "not-needed" : health.level,
        candidates: candidates.sort((a, b) => Number(a.core) - Number(b.core) || b.chars - a.chars || a.entryId.localeCompare(b.entryId)),
        authoritySections,
        policy: {
            automaticWrites: false,
            exactBytesPreferred: true,
            coreRequiresHumanOrAgentReview: true,
            note: "This planner never deletes or rewrites project knowledge. A host may apply reviewed exact-section moves with hash preconditions and manifest readback.",
        },
        advisoryOnly: true,
    };
}
